const body = $input.first().json.body || {};
const action = body.action || '';
const pr = body.pull_request || {};

if (action !== 'opened' && action !== 'synchronize') {
  return []; // ignore closed, labeled, review events, etc.
}

if (pr.draft === true) {
  return []; // skip draft PRs
}

if (!body.repository || !pr.number) {
  throw new Error('Malformed webhook payload: missing repository or PR number');
}

return [{
  json: {
    action,
    prNumber: pr.number,
    repoFullName: body.repository.full_name,
    headSHA: pr.head.sha,
    prTitle: pr.title || ''
  }
}];

const pr = $('Filter & Normalize PR').item.json;
// Fail open: if comment fetch errored, proceed with review anyway
const comments = $input.all().map(i => i.json).filter(c => !c.error);

// Bot comments embed the headSHA in their footer — use it as idempotency key
const alreadyReviewed = comments.some(c =>
  typeof c.body === 'string' && c.body.includes(pr.headSHA)
);

if (alreadyReviewed) {
  return []; // already reviewed this exact commit, stop silently
}

return [{ json: pr }];

const pr = $('Skip If Already Reviewed').item.json;
const files = $input.all().map(i => i.json).flat();

const HIGH_RISK_PATTERNS = [
  /models\/(lead|case|illustration|underwriting_item)\./,
  /models\/.*\.(write|create)\s*\(/,
  /context.*allow_case_promotion/,
  /context.*allow_state_change/,
  /context.*skip_dedup_check/,
  /_inherit\s*=/,
  /VALID_TRANSITIONS/,
  /REQUIREMENT_TO_TASK_TYPES/
];

const MEDICAL_PATTERNS = [
  /models\/medical/,
  /models\/prescription/,
  /sin_encrypted/,
  /birth_date/
];

const riskFileSet = new Set();
const complianceFileSet = new Set();
let combinedPatch = '';
const PATCH_LIMIT = 12000;

for (const f of files) {
  const p = f.filename || '';
  const patch = f.patch || '';
  combinedPatch += `\n--- ${p} ---\n${patch}\n`;

  for (const re of HIGH_RISK_PATTERNS) {
    if (re.test(p) || re.test(patch)) {
      riskFileSet.add(p);
      break;
    }
  }
  for (const re of MEDICAL_PATTERNS) {
    if (re.test(p) || re.test(patch)) {
      complianceFileSet.add(p);
      break;
    }
  }
}

const riskFiles = Array.from(riskFileSet);
const complianceFiles = Array.from(complianceFileSet);

let patch = combinedPatch;
let truncated = false;
if (combinedPatch.length > PATCH_LIMIT) {
  patch = combinedPatch.substring(0, PATCH_LIMIT);
  truncated = true;
  patch += `\n\n[DIFF TRUNCATED — first ${PATCH_LIMIT} of ${combinedPatch.length} chars shown`
        + `${files.length >= 100 ? '; PR may have >100 files, only first 100 fetched' : ''}]`;
}

return [{
  json: {
    riskFiles,
    complianceFiles,
    riskLevel: riskFiles.length > 2 ? 'HIGH' : riskFiles.length > 0 ? 'MEDIUM' : 'LOW',
    hasComplianceConcern: complianceFiles.length > 0,
    fileCount: files.length,
    patch,
    truncated,
    prNumber: pr.prNumber,
    repoFullName: pr.repoFullName,
    headSHA: pr.headSHA,
    prTitle: pr.prTitle
  }
}];

