const risk = $('Classify Risk').item.json;
const ollamaResult = $json;

const badges = {
  'HIGH':   '🔴 HIGH RISK',
  'MEDIUM': '🟡 MEDIUM RISK',
  'LOW':    '🟢 LOW RISK'
};

const review = (ollamaResult.response && typeof ollamaResult.response === 'string')
  ? ollamaResult.response.trim()
  : `*LLM review unavailable — ${ollamaResult.error || 'Ollama did not respond'}. Rule-based classification used.*`;

let body = `## ${badges[risk.riskLevel] || '⚪ UNKNOWN'} — Automated PR Review\n\n`;
body += review + '\n\n';

if (risk.truncated) {
  body += '> ⚠️ **Note:** Diff was truncated — analysis covers a partial changeset only.\n\n';
}

if (risk.hasComplianceConcern) {
  body += `### ⚠️ PIPEDA Compliance Flag\nThese files touch medical/PII data: \`${risk.complianceFiles.join('\`, \`')}\`\nEnsure field-level access controls and encryption are maintained.\n\n`;
}

body += `---\n*Auto-generated by n8n + Ollama (qwen2.5-coder:7b) — ${risk.fileCount} files analyzed · commit ${risk.headSHA.substring(0, 7)}*`;

return [{ json: { body, prNumber: risk.prNumber, repoFullName: risk.repoFullName } }];
